package com.graduation.homework.domain; import org.springframework.boot.CommandLineRunner;import org.springframework.core.annotation.Order;import org.springframework.context.annotation.*;
@org.springframework.context.annotation.Profile({"dev","test","ci"}) @Configuration public class ProjectDataSeed{@Bean @Order(10) CommandLineRunner seedProject(CourseRepository courses, AssignmentRepository assignments){return args->{if(courses.count()==0){var c=new Course();c.setCode("OPT204");c.setName("大学物理实验");c.setTeacher("王老师");c.setDescription("实验报告与过程考核");c.setStatus("ACTIVE");var saved=courses.save(c);var a=new Assignment();a.setCourseId(saved.getId());a.setTitle("干涉条纹实验报告");a.setDescription("提交数据处理、误差分析与结论");a.setDueAt(java.time.LocalDateTime.now().plusDays(14));a.setMaxScore(new java.math.BigDecimal("100"));a.setStatus("OPEN");assignments.save(a);}};}}
